export const STRINGS: Record<Lang, Strings> = { en, 'zh-TW': zhTW, 'zh-CN': zhCN, ja, ko, th, vi };

/** The panel's language: an explicit one, else the page's, else the browser's. */
export function pickLang(explicit?: string): Lang {
  for (const raw of [explicit, document.documentElement.lang, navigator.language]) {
    if (!raw) continue;
    const l = raw.toLowerCase();
    if (l.startsWith('zh')) return /tw|hk|mo|hant/.test(l) ? 'zh-TW' : 'zh-CN';
    for (const k of ['ja', 'ko', 'th', 'vi', 'en'] as const) if (l.startsWith(k)) return k;
  }
  return 'en';
}

/** The language a reply is written in, by its script, for reading it aloud; fallback when it can't tell. */
export function textLang(text: string, fallback: Lang): Lang {
  if (/[\u3040-\u30ff]/.test(text)) return 'ja';
  if (/[\uac00-\ud7af]/.test(text)) return 'ko';
  if (/[\u0e00-\u0e7f]/.test(text)) return 'th';
  if (/[\u4e00-\u9fff]/.test(text)) return fallback.startsWith('zh') ? fallback : /[這個們說來時會為]/.test(text) ? 'zh-TW' : 'zh-CN';
  if (/[ăâđêôơưạảấầẩẫậắằẳẵặẹẻẽếềểễệỉịọỏốồổỗộớờởỡợụủứừửữựỳỵỷỹ]/i.test(text)) return 'vi';
  if (/^[\x00-\x7f\u2018-\u201d\u2026\u2013\u2014]*$/.test(text)) return 'en';
  return fallback;
}

export function t(lang: Lang, key: keyof Strings, vars: Record<string, string | number> = {}): string {
  return (STRINGS[lang][key] ?? en[key]).replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ''));
}

export type StringKey = keyof Strings;
